def find_anagrams(s, p):
    # Finds exact copies of p. Make it find anagrams.
    return [i for i in range(len(s)) if s[i:i + len(p)] == p]

widget.solution:
def find_anagrams(s, p):
    need = {}
    for ch in p:
        need[ch] = need.get(ch, 0) + 1
    have = {}
    out = []
    for i, ch in enumerate(s):
        have[ch] = have.get(ch, 0) + 1
        if i >= len(p):
            old = s[i - len(p)]
            have[old] -= 1
            if have[old] == 0:
                del have[old]
        if have == need:
            out.append(i - len(p) + 1)
    return out

